insert into change_headers (id, ts) values (67, '2026-10-13') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (67, 'ru', 'Калькулятор стоимости и калькулятор стоимости для Форм жизни: очки за постройки и исследования больше не уменьшаются от скидок на стоимость (Мегалит, Центр исследования минералов, снижение стоимости исследований). Игра начисляет очки по полной стоимости, и теперь калькуляторы считают так же.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'en', 'Costs calculator and Lifeform costs calculator: the points for buildings and research no longer drop with cost reductions (Megalith, Mineral Research Centre, research cost reduction). The game awards points for the full cost, and the calculators now count them the same way.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'pt', 'Calculadora de custos e calculadora de custos das Formas de Vida: os pontos de edifícios e pesquisas já não diminuem com as reduções de custo (Megálito, Centro de Pesquisa de Minerais, redução do custo das pesquisas). O jogo atribui os pontos pelo custo total, e as calculadoras agora contam da mesma forma.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'de', 'Kostenberechnung und Kostenberechnung für Lebensformen: Die Punkte für Gebäude und Forschungen sinken nicht mehr durch Kostenreduktionen (Felsenmonument, Mineral-Forschungszentrum, Reduktion der Forschungskosten). Das Spiel vergibt die Punkte nach den vollen Kosten, und die Rechner zählen jetzt genauso.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'pl', 'Kalkulator kosztów i kalkulator kosztów Form Życia: punkty za budynki i badania nie maleją już przez obniżki kosztów (Monument Skalny, Centrum Badań Minerałów, obniżenie kosztów badań). Gra przyznaje punkty według pełnego kosztu i kalkulatory liczą je teraz tak samo.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'es', 'Calculadora de costes y calculadora de costes de Formas de Vida: los puntos de edificios e investigaciones ya no bajan con las reducciones de coste (Litomonumento, Centro de Investigación de Minerales, reducción del coste de investigación). El juego otorga los puntos según el coste completo, y las calculadoras ahora los cuentan igual.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'fr', 'Calculateur de coûts et calculateur de coûts des Formes de vie : les points des bâtiments et des recherches ne baissent plus avec les réductions de coût (Monument rocheux, Centre de recherche sur les minéraux, réduction du coût des recherches). Le jeu attribue les points selon le coût complet, et les calculateurs les comptent désormais de la même façon.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'it', 'Calcolatore di costi e calcolatore di costi delle Forme di vita: i punti di edifici e ricerche non diminuiscono più con le riduzioni dei costi (Monolite, Centro di Mineralogia, riduzione del costo delle ricerche). Il gioco assegna i punti in base al costo pieno, e ora i calcolatori li contano allo stesso modo.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'nl', 'Kostenberekening en kostenberekening voor Levensvormen: de punten voor gebouwen en onderzoek dalen niet meer door kostenreducties (Megaliet, Mineralen Onderzoekscentrum, verlaging van de onderzoekskosten). Het spel kent punten toe op basis van de volledige kosten, en de calculators tellen nu op dezelfde manier.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'sk', 'Kalkulátor cien a kalkulátor cien pre Formy života: body za budovy a výskumy sa už neznižujú zľavami z ceny (Megalit, Výskumné centrum minerálov, zníženie ceny výskumov). Hra udeľuje body podľa plnej ceny a kalkulátory ich teraz počítajú rovnako.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'tr', 'Maliyet hesaplayıcı ve Yaşam Formları maliyet hesaplayıcı: binalar ve araştırmalar için verilen puanlar artık maliyet indirimleriyle (Kaya Anıtı, Maden Araştırma Merkezi, araştırma maliyeti indirimi) azalmıyor. Oyun puanları tam maliyet üzerinden verir ve hesaplayıcılar artık aynı şekilde hesaplıyor.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (67, 'bs', 'Kalkulator troškova i kalkulator troškova za Oblike života: bodovi za zgrade i istraživanja više se ne smanjuju zbog sniženja troškova (Megalith, Mineral Research Centre, smanjenje troškova istraživanja). Igra dodjeljuje bodove prema punom trošku, a kalkulatori ih sada računaju na isti način.') on duplicate key update description = values(description);
